-- Requires the private pre-migration snapshot. Updates only one exact recognized footer per article.
WITH candidates AS (SELECT a.id,a.body,'<p>Conteúdo preparado com auxílio de inteligência artificial, a partir de informações '||v.preposition||' '||replace(replace(replace(replace(replace(s.name,'&','&amp;'),'<','&lt;'),'>','&gt;'),'"','&quot;'),chr(39),'&#39;')||'. <a href='||q.mark||replace(replace(replace(replace(replace(i.url,'&','&amp;'),'<','&lt;'),'>','&gt;'),'"','&quot;'),chr(39),'&#39;')||q.mark||'>Leia a publicação original</a>.</p>' AS previous,'<p>Conteúdo preparado a partir de informações de '||replace(replace(replace(replace(replace(s.name,'&','&amp;'),'<','&lt;'),'>','&gt;'),'"','&quot;'),chr(39),'&#39;')||'. <a href="'||replace(replace(replace(replace(replace(i.url,'&','&amp;'),'<','&lt;'),'>','&gt;'),'"','&quot;'),chr(39),'&#39;')||'">Leia a publicação original</a>.</p>' AS next FROM giro63.articles a JOIN giro63.automation_items i ON i.article_id=a.id JOIN giro63.automation_sources s ON s.id=i.source_id CROSS JOIN (VALUES ('de'),('da'),('do')) v(preposition) CROSS JOIN (VALUES ('"'),(chr(92)||'"')) q(mark)), matched AS (SELECT * FROM candidates WHERE length(body)-length(replace(body,previous,''))=length(previous)), unique_match AS (SELECT id FROM matched GROUP BY id HAVING count(*)=1) UPDATE giro63.articles a SET body=replace(m.body,m.previous,m.next) FROM matched m JOIN unique_match u ON u.id=m.id WHERE a.id=m.id AND a.body=m.body AND EXISTS(SELECT 1 FROM giro63_backup_20261107.articles_before_publication_review b WHERE b.id=a.id AND b.body=a.body) RETURNING a.id;
